import type { ProjectionWatermark } from '../render/remote/projection-state.js';

/** Cold-path diagnostic copy. Decimal strings keep all u64 bits in JSON exports. */
export type ProgressCursor = Readonly<{
  worldId: string; shardId: string; systemId: string; subscriptionId: string;
  ownerEpoch: string; recoveryGeneration: string; streamGeneration: string; sequence: string; systemRevision: string;
}>;
export type ProjectionProgress = Readonly<{
  owner: 'network' | 'render'; connectionGeneration: number;
  received?: ProgressCursor; applied?: ProgressCursor;
  queuedBytes: number; queuedBatches: number; inFlightBytes: number; inFlightBatches: number;
}>;
export function progressCursor(value: ProjectionWatermark | null | undefined): ProgressCursor | undefined {
  if (!value) return;
  return { ...value.scope, subscriptionId: value.subscriptionId,
    ownerEpoch: String(value.scope.ownerEpoch), recoveryGeneration: String(value.scope.recoveryGeneration),
    streamGeneration: String(value.streamGeneration), sequence: String(value.sequence), systemRevision: String(value.systemRevision) };
}
