/** Small observer values. These never seed commands, previews or render state. */
export type StrategicFrontier = { connectionGeneration: number; interestGeneration: bigint; sequence: bigint };
export type StrategicInterest = { connectionGeneration: number; interestGeneration: bigint; systemIds: readonly string[] };
export type StrategicRow = {
  scope: { worldId: string; shardId: string; systemId: string; ownerEpoch: bigint; recoveryGeneration: bigint };
  counts?: { systemRevision: bigint; committedServerTimeMs: bigint; presentShips: number; movingShips: number };
};
export type StrategicSnapshot = StrategicFrontier & {
  status: 'pending' | 'view' | 'rejected' | 'unavailable'; systems: readonly StrategicRow[];
  rejectionReason?: number;
};
export const STRATEGIC_PAGE_SIZE = 32;
export function compareStrategic(a: StrategicFrontier, b: StrategicFrontier): number {
  if (a.connectionGeneration !== b.connectionGeneration) return Math.sign(a.connectionGeneration - b.connectionGeneration);
  if (a.interestGeneration !== b.interestGeneration) return a.interestGeneration < b.interestGeneration ? -1 : 1;
  return a.sequence === b.sequence ? 0 : a.sequence < b.sequence ? -1 : 1;
}
export function strategicDisposed(error: unknown): boolean {
  if (!error || typeof error !== 'object' || !('code' in error)) return false;
  return error.code === 'DISPOSED' || error.code === 'CANCELED';
}
