/** Server time observed at a browser monotonic instant. RTT is uncertainty,
 * never proof that clocks on distinct servers share an epoch or offset. */
export type ServerClockAnchor = {
  serverMs: bigint; monotonicMs: number; timeOriginMs: number; roundTripMs: number;
};

/** Only relative time enters the visual clock; authoritative u64 time stays
 * bigint. The final number is presentation precision, never a rule deadline. */
export function serverTimeForPresentation(serverMs: bigint, anchor: ServerClockAnchor,
  localMonotonicEpochMs: number, localFrameWallMs: number): number {
  return localFrameWallMs + Number(serverMs - anchor.serverMs)
    + anchor.timeOriginMs + anchor.monotonicMs - localMonotonicEpochMs;
}

export function validateServerClock(anchor: ServerClockAnchor): void {
  if (typeof anchor.serverMs !== "bigint" || anchor.serverMs < 0n || anchor.serverMs > 0xffffffffffffffffn
    || ![anchor.monotonicMs, anchor.timeOriginMs, anchor.roundTripMs].every(Number.isFinite)
    || anchor.monotonicMs < 0 || anchor.roundTripMs < 0) throw new Error("Invalid server clock observation");
}
