import type { ProjectionBatch } from "./contracts.js";

/** A dedicated port belongs to one stream lifetime, never to the broker's payload path. */
export type TransferPort = Pick<MessagePort, "postMessage" | "addEventListener" | "removeEventListener" | "start" | "close">;
export type ProjectionPacket = {
  type: "projection";
  connectionGeneration: number;
  ticket: number;
  batch: ProjectionBatch;
};
export type ReleasedPacket = {
  type: "released";
  connectionGeneration: number;
  ticket: number;
  buffers: ArrayBuffer[];
};

export function validStreamOptions(generation: number, maxBytes: number, maxBatches: number): void {
  for (const value of [generation, maxBytes, maxBatches]) {
    if (!Number.isSafeInteger(value) || value < 1) throw new RangeError("Stream budgets and generation must be positive safe integers");
  }
}
