/** Local projection format. Wire DTOs and GPU storage layouts are independent. */
import type { ServerClockAnchor } from "../../contracts/server-clock.js";
import type { ProjectionTrace } from '../../contracts/causal-context.js';
export type ProjectionScope = {
  worldId: string;
  shardId: string;
  systemId: string;
  ownerEpoch: bigint;
  recoveryGeneration: bigint;
};

export type ProjectionBatch = {
  layoutVersion: 1;
  scope: ProjectionScope;
  subscriptionId: string;
  streamGeneration: bigint;
  sequence: bigint;
  baseSystemRevision: bigint;
  systemRevision: bigint;
  /** Same-port metadata removes a dependency on UI welcome-event ordering. */
  clock?: ServerClockAnchor;
  /** Optional selected diagnostic context, never a domain identity or buffer copy. */
  trace?: ProjectionTrace;
  snapshot?: { id: string; index: number; count: number };
  /** UUID bytes, 16 per upsert; slots are allocated only by the renderer. */
  ids: Uint8Array;
  revisions: BigUint64Array;
  /** f64 sun-local XZ start/rest positions and movement targets. */
  positions: Float64Array;
  targets: Float64Array;
  /** Departure/arrival server milliseconds, two per upsert. */
  times: BigUint64Array;
  moving: Uint8Array;
  removedIds: Uint8Array;
};

export const MAX_BATCH_ENTITIES = 256;
export const MAX_STREAM_BYTES = 1024 * 1024;
export const MAX_STREAM_BATCHES = 4;
export const MAX_SNAPSHOT_ENTITIES = 16_384;
export const MAX_SNAPSHOT_BYTES = 4 * 1024 * 1024;

/** Structural validation is bounded by a fixed number of views, not entity count. */
export function projectionBuffers(batch: ProjectionBatch): ArrayBuffer[] {
  const count = batch.ids.byteLength / 16;
  const removed = batch.removedIds.byteLength / 16;
  if (batch.layoutVersion !== 1 || !Number.isInteger(count) || !Number.isInteger(removed)
    || count + removed > MAX_BATCH_ENTITIES) throw new Error("Invalid projection batch size/layout");
  const views = [batch.ids, batch.revisions, batch.positions, batch.targets, batch.times, batch.moving, batch.removedIds];
  const lengths = [count * 16, count * 8, count * 16, count * 16, count * 16, count, removed * 16];
  const constructors = [Uint8Array, BigUint64Array, Float64Array, Float64Array, BigUint64Array, Uint8Array, Uint8Array];
  const buffers = new Set<ArrayBuffer>();
  for (let i = 0; i < views.length; i++) {
    const view = views[i];
    if (!(view instanceof constructors[i]) || view.byteLength !== lengths[i]
      || !(view.buffer instanceof ArrayBuffer)) throw new Error("Invalid projection column");
    buffers.add(view.buffer);
  }
  return [...buffers];
}

export function bufferBytes(buffers: readonly ArrayBuffer[]): number {
  let bytes = 0;
  for (const buffer of buffers) bytes += buffer.byteLength;
  return bytes;
}
